'use strict';
// Development-only compiler. The generated index.html needs no build or server.
const fs = require('node:fs'), path = require('node:path'), crypto = require('node:crypto');
const babel = require('@babel/core'), reactPreset = require('@babel/preset-react');
const vm = require('node:vm');
const postcss = require('postcss'), tailwind = require('tailwindcss');
const root = path.resolve(__dirname, '..');
const normalize = text => text.replace(/\r\n/g, '\n');
const read = filename => normalize(fs.readFileSync(path.join(root, filename), 'utf8'));
const sha = data => crypto.createHash('sha256').update(data).digest('hex');
const scriptSafe = text => text.replace(/<\/script/gi, '<\\/script').replace(/^\/\/[#@] sourceMappingURL=.*$/gm, '');
const runtime = [
  { name: 'react', version: '18.3.1', file: 'umd/react.production.min.js', license: 'LICENSE', expectedSHA256: 'd949f1c3687aedadcedac85261865f29b17cd273997e7f6b2bfc53b2f9d4c4dd' },
  { name: 'react-dom', version: '18.3.1', file: 'umd/react-dom.production.min.js', license: 'LICENSE', expectedSHA256: '35f4f974f4b2bcd44da73963347f8952e341f83909e4498227d4e26b98f66f0d' },
  { name: 'jspdf', version: '2.5.1', file: 'dist/jspdf.umd.min.js', license: 'LICENSE', expectedSHA256: '98ccf17aa10c20bb1301762618fcc9b6ab3a4e7f26b6071d64d0b41154df3875' }
];

async function generate() {
  const html = read('bingo_wuerfel_app_ver1.4.html');
  const jsx = html.match(/<script type="text\/babel">([\s\S]*?)<\/script>/)?.[1];
  if (!jsx) throw Error('The authoring JSX block is missing.');
  const packageJson = JSON.parse(read('package.json'));
  const versions = {};
  for (const [name, expected] of Object.entries(packageJson.devDependencies)) {
    const actual = JSON.parse(read(`node_modules/${name}/package.json`)).version;
    if (actual !== expected) throw Error(`${name}: expected ${expected}, found ${actual}. Run npm ci.`);
    versions[name] = actual;
  }
  const externals = [...html.matchAll(/<script\b[^>]*\bsrc="([^"]+)"[^>]*><\/script>/g)];
  if (externals.length !== 5) throw Error('Unexpected authoring runtime imports; review the standalone build.');
  const compiled = babel.transformSync(jsx, {
    filename: 'bingo-app.jsx', presets: [[reactPreset, { runtime: 'classic', development: false }]],
    configFile: false, babelrc: false, comments: true, compact: false, sourceMaps: false
  }).code;
  // All utility candidates are complete literals. Inline style values stay inline.
  const css = (await postcss([tailwind({ content: [{ raw: html, extension: 'html' }], theme: { extend: {} }, plugins: [] })])
    .process('@tailwind base;\n@tailwind components;\n@tailwind utilities;\n', { from: undefined })).css;
  if (/@import\b|url\(\s*['"]?https?:/i.test(css)) throw Error('CSS contains an external resource.');
  const libraries = runtime.map(entry => {
    const source = read(`node_modules/${entry.name}/${entry.file}`);
    if (sha(source) !== entry.expectedSHA256) throw Error(`Runtime bytes changed: ${entry.name}. Run npm ci and inspect the dependency.`);
    return { ...entry, source, sha256: sha(source) };
  });
  const notices = [...runtime, { name: 'tailwindcss', version: versions.tailwindcss, license: 'LICENSE' }]
    .map(entry => `${entry.name} ${entry.version}\n${read(`node_modules/${entry.name}/${entry.license}`)}`).join('\n\n');
  const info = {
    format: 'MATHE-BINGO-STANDALONE', version: 1,
    authoringSHA256: sha(html), jsxSHA256: sha(jsx), compiledSHA256: sha(compiled), cssSHA256: sha(css),
    lockSHA256: sha(read('package-lock.json')), buildTools: versions,
    runtime: libraries.map(({ name, version, sha256 }) => ({ name, version, sha256 }))
  };
  let product = html.replace(/\s*<script\b[^>]*\bsrc="[^"]+"[^>]*><\/script>/g, '');
  product = product.replace('  <style>', () => `  <style id="bingo-utilities">\n${css}\n  </style>\n  <style>`);
  product = product.replace('  <style id="bingo-utilities">', () => libraries.map(lib => `  <script data-runtime="${lib.name}" data-version="${lib.version}">\n${scriptSafe(lib.source)}\n  </script>`).join('\n') + '\n  <style id="bingo-utilities">');
  product = product.replace('<div id="root"></div>', '<noscript>Mathe-Bingo benötigt eingeschaltetes JavaScript. Die fertige Datei funktioniert ohne Internet.</noscript>\n  <div id="root"></div>');
  product = product.replace(/<script type="text\/babel">[\s\S]*?<\/script>/,
    () => `<script id="bingo-build-info" type="application/json">${JSON.stringify(info)}</script>\n  <script id="bingo-app">\n${scriptSafe(compiled)}\n  </script>`);
  // Anchor the document end: jsPDF itself contains literal HTML examples.
  product = product.replace(/<\/body>\s*<\/html>\s*$/, () => `<!-- Embedded third-party licenses\n${notices.replace(/--/g, '—')}\n-->\n</body>\n</html>`);
  product = '<!-- Generated by tools/build_standalone.js; edit bingo_wuerfel_app_ver1.4.html instead. -->\n' + product;
  // Library strings can contain example HTML; inspect actual markup only.
  const markup = product.replace(/(<script\b[^>]*>)[\s\S]*?<\/script>/gi, '$1</script>');
  if (/<script\b[^>]*\bsrc=|<link\b[^>]*\b(?:href|rel)=|<script\b[^>]*type="text\/babel"/i.test(markup)) throw Error('The output still requires a runtime resource.');
  const blocks = [...product.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)];
  if (blocks.length !== 5) throw Error('Unexpected inline script boundaries.');
  for (const [index, block] of blocks.entries()) if (!block[1].includes('application/json')) {
    try { new vm.Script(block[2], { filename: `standalone-script-${index}.js` }); }
    catch (error) { throw Error(`Inline script ${index} (${block[1].trim()}): ${error.message}`); }
  }
  if (blocks.at(-1)[2].trim() !== scriptSafe(compiled).trim()) throw Error('Compiled JavaScript changed during embedding.');
  product = product.trimEnd() + '\n';
  return { product, info, sha256: sha(product), bytes: Buffer.byteLength(product) };
}

async function main() {
  const result = await generate();
  const filename = path.join(root, 'index.html');
  if (process.argv.includes('--check')) {
    if (!fs.existsSync(filename) || !fs.readFileSync(filename).equals(Buffer.from(result.product))) throw Error('index.html is stale. Run npm run build.');
  } else {
    const output = path.join(root, 'output/portable');
    fs.mkdirSync(output, { recursive: true });
    const unexpected = fs.readdirSync(output).filter(name => name !== 'index.html');
    if (unexpected.length) throw Error('The delivery folder contains unexpected files; nothing was deleted: ' + unexpected.join(', '));
    fs.writeFileSync(filename, result.product);
    fs.writeFileSync(path.join(output, 'index.html'), result.product);
  }
  console.log(JSON.stringify({ action: process.argv.includes('--check') ? 'verified' : 'built', bytes: result.bytes, sha256: result.sha256, ...result.info }, null, 2));
}
module.exports = { generate };
if (require.main === module) main().catch(error => { console.error(error.message); process.exitCode = 1; });
